<script setup lang="ts">import { Plus, Search, Star } from 'lucide-vue-next'; import { ref, computed } from 'vue'; import { useAppStore } from '@/stores/app'; import type { Project } from '@/types'; const app=useAppStore(); const query=ref(''); const filtered=computed(()=>app.currentProjects.filter(p=>p.name.toLowerCase().includes(query.value.toLowerCase()))); const progress=(p:Project)=>p.taskCount ? Math.round(p.completedCount/p.taskCount*100) : 0</script>
<template><div class="page"><header class="page-header"><div><h1>Projects</h1><p>Plan and organize work inside {{app.currentWorkspace?.name}}.</p></div><RouterLink to="/projects/new" class="btn btn-primary"><Plus :size="16"/>Create project</RouterLink></header><div class="toolbar"><div class="search-input"><Search :size="16"/><input v-model="query" placeholder="Search projects"/></div><select><option>All projects</option><option>Favorites</option><option>Recently viewed</option></select><select><option>Sort by updated</option><option>Sort by name</option></select></div><section class="projects-table"><div class="table-header"><span>Project</span><span>Lead</span><span>Progress</span><span>Updated</span><span></span></div><RouterLink v-for="p in filtered" :key="p.id" :to="`/projects/${p.id}/overview`" class="project-table-row"><span class="project-name-cell"><span class="project-icon" :style="{background:p.color}">{{p.key[0]}}</span><span><strong>{{p.name}}</strong><small>{{p.key}} · {{p.description}}</small></span></span><span>{{p.lead.name}}</span><span><span class="progress"><i :style="{width:`${progress(p)}%`}"></i></span><small>{{p.completedCount}} / {{p.taskCount}}</small></span><span>{{p.updatedAt}}</span><Star :size="16" :class="{filled:p.favorite}"/></RouterLink></section></div></template>
